import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { uploadJob } from "../api";

export default function Jobs() {
  const [jdText, setJdText] = useState("");
  const [jdFile, setJdFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [jdUploaded, setJdUploaded] = useState(false);

  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    if (jdFile) {
      formData.append("jd_file", jdFile);
    } else {
      formData.append("jd_text", jdText);
    }

    try {
      setLoading(true);
      setMessage("");
      await uploadJob(formData);
      setMessage("Job Description uploaded successfully");
      setJdUploaded(true);
    } catch {
      setMessage("Failed to upload Job Description");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="page-wrapper">
      <div className="container-fluid px-5">
        <h2 className="page-title">Add Job Description</h2>
        <p className="page-subtitle">
          Upload or paste the job description to begin screening.
        </p>

        <div className="theme-card jd-narrow">
          <form onSubmit={handleSubmit}>
            <label className="mb-2">Job Description Text</label>
            <textarea
              className="theme-textarea mb-4"
              placeholder="Paste job description here (optional)"
              value={jdText}
              onChange={(e) => setJdText(e.target.value)}
            />

            <label className="mb-2">Upload JD File (PDF / DOCX)</label>
            <input
              type="file"
              accept=".pdf,.docx"
              className="theme-input mb-4"
              onChange={(e) => setJdFile(e.target.files[0])}
            />

            <button className="theme-btn" type="submit" disabled={loading}>
              {loading ? "Uploading..." : "Upload JD"}
            </button>

            {message && (
              <p className="mt-3" style={{ color: "#bdbdbd" }}>
                {message}
              </p>
            )}

            {jdUploaded && (
              <div className="mt-4">
                <button
                  type="button"
                  className="theme-btn"
                  onClick={() => navigate("/resumes")}
                >
                  Add Resumes →
                </button>
              </div>
            )}
          </form>
        </div>
      </div>
    </div>
  );
}
